## Motivation

Dynamic tools can be accepted by `thread/start` and still fail later when the model backend sees their `inputSchema`. Before this change, that delayed backend rejection could leave the app-server thread in `systemError` while the useful diagnostic was only written to app-server stderr:

```text
invalid_function_parameters ... Invalid schema for function 'create': schema must be a JSON Schema of 'type: "object"', got 'type: "None"'
```

That is a client-facing problem: app-server clients cannot build an actionable error UI from stderr, and `thread/start`, `turn/start`, `thread/read`, and status notifications did not reliably expose the rejected tool or schema path.

This PR intentionally does not add app-server preflight schema rejection. Preflight would risk drifting from the Responses API's actual accepted subset. Instead, when the backend rejects a dynamic tool schema, app-server now preserves the backend error and enriches it with the dynamic tool context clients need.

## What changed

- Adds typed `TurnErrorData::DynamicToolInputSchema` data for backend dynamic tool schema failures.
- Reports the backend, underlying error, dynamic tool namespace/name/qualified name, schema path such as `dynamicTools[0].inputSchema.anyOf`, and remediation text.
- Handles ambiguous bare backend function names by returning `toolCandidates` instead of silently dropping diagnostics.
- Preserves enriched errors through live `error` notifications, `thread/read`, and `thread/turns/list`, including the window where a turn has errored but terminal history has not been materialized yet.
- Updates app-server docs plus generated v2 JSON Schema and TypeScript fixtures.

## Minimal repro

This script starts a local app-server and a tiny mock Responses endpoint. The mock returns the same backend schema rejection shape that used to be visible only in stderr. The script asserts that the structured diagnostic is now present in both the live `error` notification and `thread/read`.

From the repo root:

```shell
cargo build -p codex-app-server
node repro-dynamic-tool-schema-error.mjs
```

`repro-dynamic-tool-schema-error.mjs`:

```js
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import readline from "node:readline";

const backendError =
  "invalid_function_parameters ... Invalid schema for function 'create': schema must be a JSON Schema of 'type: \"object\"', got 'type: \"None\"'";

const mock = createServer((req, res) => {
  req.resume();
  res.writeHead(400, { "content-type": "application/json" });
  res.end(JSON.stringify({ error: { message: backendError } }));
});
await new Promise((resolve) => mock.listen(0, "127.0.0.1", resolve));

const codexHome = await mkdtemp(join(tmpdir(), "codex-dynamic-tool-schema-"));
await writeFile(
  join(codexHome, "config.toml"),
  `
model = "mock-model"
approval_policy = "never"
sandbox_mode = "read-only"
model_provider = "mock_provider"

[model_providers.mock_provider]
name = "Mock provider"
base_url = "http://127.0.0.1:${mock.address().port}/v1"
wire_api = "responses"
request_max_retries = 0
stream_max_retries = 0
`,
);

const appServer = process.env.CODEX_APP_SERVER ?? "./codex-rs/target/debug/codex-app-server";
const child = spawn(appServer, ["--listen", "stdio://"], {
  env: { ...process.env, CODEX_HOME: codexHome },
  stdio: ["pipe", "pipe", "ignore"],
});
const rl = readline.createInterface({ input: child.stdout });
const buffered = [];
let nextId = 1;

async function readLineMessage() {
  const line = await new Promise((resolve) => rl.once("line", resolve));
  return JSON.parse(line);
}

function takeBuffered(predicate) {
  const index = buffered.findIndex(predicate);
  if (index === -1) {
    return undefined;
  }
  const [message] = buffered.splice(index, 1);
  return message;
}

async function request(method, params) {
  const id = nextId++;
  child.stdin.write(JSON.stringify({ id, method, params }) + "\n");
  for (;;) {
    const message = takeBuffered((candidate) => candidate.id === id);
    if (message) {
      return message;
    }
    buffered.push(await readLineMessage());
  }
}

async function notification(method) {
  for (;;) {
    const message = takeBuffered((candidate) => candidate.method === method);
    if (message) {
      return message;
    }
    buffered.push(await readLineMessage());
  }
}

function assertDynamicToolError(data, source) {
  if (data?.reason !== "dynamicToolInputSchema") {
    throw new Error(`${source}: missing structured dynamic tool schema error`);
  }
  if (data.tool?.qualifiedName !== "repro.create") {
    throw new Error(`${source}: wrong tool`);
  }
  if (data.schemaPath !== "dynamicTools[0].inputSchema.anyOf") {
    throw new Error(`${source}: wrong schema path`);
  }
  if (data.underlyingError !== backendError) {
    throw new Error(`${source}: wrong underlying error`);
  }
}

try {
  await request("initialize", {
    capabilities: { experimentalApi: true, optOutNotificationMethods: [] },
    clientInfo: { name: "dynamic-tool-schema-repro", version: "0.0.0" },
  });
  child.stdin.write(JSON.stringify({ method: "initialized" }) + "\n");

  const thread = await request("thread/start", {
    dynamicTools: [
      {
        namespace: "repro",
        name: "create",
        description: "Top-level anyOf repro tool.",
        inputSchema: {
          anyOf: [
            {
              type: "object",
              properties: { kind: { type: "string", enum: ["a"] } },
              required: ["kind"],
              additionalProperties: false,
            },
            {
              type: "object",
              properties: { kind: { type: "string", enum: ["b"] } },
              required: ["kind"],
              additionalProperties: false,
            },
          ],
        },
      },
    ],
  });
  const threadId = thread.result.thread.id;

  await request("turn/start", {
    threadId,
    input: [{ type: "text", text: "hello", text_elements: [] }],
  });

  const liveError = await notification("error");
  assertDynamicToolError(liveError.params.error.data, "error notification");
  await notification("turn/completed");

  const read = await request("thread/read", { threadId, includeTurns: true });
  const failedTurn = read.result.thread.turns.find((turn) => turn.status === "failed");
  assertDynamicToolError(failedTurn?.error?.data, "thread/read");

  console.log(JSON.stringify(liveError.params.error.data, null, 2));
} finally {
  child.kill("SIGTERM");
  await new Promise((resolve) => mock.close(resolve));
  await rm(codexHome, { recursive: true, force: true });
}
```

Local output:

```json
{
  "backend": "Responses API",
  "reason": "dynamicToolInputSchema",
  "remediation": "Adjust the dynamic tool inputSchema to the JSON Schema subset accepted by the model backend. For discriminated unions, wrap the union in a top-level object property or flatten it into one object schema.",
  "schemaPath": "dynamicTools[0].inputSchema.anyOf",
  "tool": {
    "index": 0,
    "name": "create",
    "namespace": "repro",
    "qualifiedName": "repro.create"
  },
  "toolCandidates": [],
  "underlyingError": "invalid_function_parameters ... Invalid schema for function 'create': schema must be a JSON Schema of 'type: \"object\"', got 'type: \"None\"'"
}
```

## Validation

- `node /tmp/repro-dynamic-tool-schema-error.mjs`
- `cargo test -p codex-app-server-protocol`
- `env RUST_MIN_STACK=16777216 cargo test -p codex-app-server backend_dynamic_tool_schema_error_is_reported_to_clients`
- `cargo test -p codex-app-server validate_dynamic_tools`
- `cargo test -p codex-analytics`
- `cargo test -p codex-exec event_processor_with_json_output`
- `env RUST_MIN_STACK=16777216 cargo test -p codex-tui app_server`

Note: a full local `cargo test -p codex-app-server` run hit unrelated local sandbox/seatbelt failures in command execution tests (`sandbox_apply: Operation not permitted`) plus an existing local file-watcher timeout; the new dynamic tool schema coverage passed in that run.
